// Generated by Senne 0.1.0 from:
//   read the lines of "prices.txt", spawn 8 workers, each trims the line and parses it as
//   a decimal, and if it fails, log the error and continue. After that, sum them and
//   print the total.
// Same sentence in, same code out. Change the sentence, not this file.

use std::error::Error;
use std::fs;
use std::thread;

pub fn run() -> Result<(), Box<dyn Error>> {
    // read the lines of "prices.txt"  [read_lines/collect + propagate]
    let lines = fs::read_to_string("prices.txt").map(|text| text.lines().map(str::to_owned).collect::<Vec<_>>())?;
    // spawn 8 workers, each  [parallel/scoped_fixed]
    let workers = 8;
    let chunk_size = lines.len().div_ceil(workers).max(1);
    let values: Vec<f64> = thread::scope(|s| {
        let handles: Vec<_> = lines
            .chunks(chunk_size)
            .map(|chunk| {
                s.spawn(move || {
                    let mut out = Vec::new();
                    for line in chunk {
                        // trims the line  [trim/trim]
                        let line = line.trim();
                        // parses it as a decimal  [parse_number/parse + handle]
                        let x = match line.trim().parse::<f64>() {
                            Ok(value) => value,
                            Err(err) => {
                                eprintln!("could not parse {line:?} as a decimal number: {err}");
                                continue;
                            }
                        };
                        out.push(x);
                    }
                    out
                })
            })
            .collect();
        handles
            .into_iter()
            .flat_map(|handle| handle.join().expect("worker thread panicked"))
            .collect()
    });
    // sum them  [sum/iter_sum]
    let total: f64 = values.iter().sum();
    // print the total  [print/display]
    println!("{total}");
    Ok(())
}
